/// Computes the greatest common divisor (GCD) of two positive `u32` values.
///
/// Preconditions: `m > 0` and `n > 0`.
/// Postcondition: returns the mathematical gcd(m, n) as a positive `u32`.
pub fn gcd_calc(m: u32, n: u32) -> u32 {
    debug_assert!(m > 0 && n > 0);

    // Euclidean algorithm (remainder form).
    // Invariant: gcd(a, b) == gcd(m, n) throughout.
    // Termination: when b != 0, the next b is (a % b) which is strictly less than b,
    // so b strictly decreases and must reach 0 in finitely many steps.
    let mut a = m;
    let mut b = n;

    while b != 0 {
        let r = a % b;
        a = b;
        b = r;
    }

    // Since m,n > 0, the gcd is positive; a holds the gcd when b == 0.
    a
}

